def completar_existentes(apps, schema_editor):
    """Los comunicados enviados antes: se publicaron y se avisaron al crearse. Sus estudiantes cuentan en el grupo de su
    inscripción vigente y cada tutor, en el de su primer hijo inscrito (para «Lectura por grupo»)."""
    Comunicado = apps.get_model('Comunicados', 'Comunicado')
    Destinatario = apps.get_model('Comunicados', 'Destinatario')
    Inscripcion = apps.get_model('Alumnos', 'Inscripcion')
    TutorAlumno = apps.get_model('Alumnos', 'TutorAlumno')
    for comunicado in Comunicado.objects.all().only('pk', 'creado'):
        Comunicado.objects.filter(pk=comunicado.pk).update(publicado_en=comunicado.creado, avisado_en=comunicado.creado)
    grupos = dict(Inscripcion.objects.filter(activa=True, ciclo__activo=True).values_list('alumno_id', 'grupo_id'))
    if not grupos:
        return
    for destinatario in Destinatario.objects.filter(tipo='ESTUDIANTE', alumno_id__in=list(grupos)).only('pk', 'alumno_id'):
        Destinatario.objects.filter(pk=destinatario.pk).update(grupo_id=grupos[destinatario.alumno_id])
    primer_hijo = {}
    for tutor_id, alumno_id in TutorAlumno.objects.filter(activo=True).order_by('pk').values_list('tutor_id', 'alumno_id'):
        if alumno_id in grupos:
            primer_hijo.setdefault(tutor_id, grupos[alumno_id])
    for destinatario in Destinatario.objects.filter(tipo='TUTOR', tutor_id__in=list(primer_hijo)).only('pk', 'tutor_id'):
        Destinatario.objects.filter(pk=destinatario.pk).update(grupo_id=primer_hijo[destinatario.tutor_id])


